"use client";
import { Check } from "lucide-react";
import { useState, useEffect } from "react";

interface Feature {
  name: string;
  included?: boolean;
}

interface Package {
  id: string;
  name: string;
  slug: string;
  description?: string;
  price: number;
  currency: string;
  features: Feature[];
  isPopular: boolean;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export default function PackagesPage() {
  const [packages, setPackages] = useState<Package[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [billingCycle, setBillingCycle] = useState<"monthly" | "yearly">("yearly");

  useEffect(() => {
    fetchPackages();
  }, []);

  const fetchPackages = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/packages");
      
      if (!response.ok) {
        throw new Error("Failed to fetch packages");
      }

      const data = await response.json();
      setPackages(data.packages || data);
      setError(null);
    } catch (err) {
      console.error("Error fetching packages:", err);
      setError("Failed to load packages. Please try again later.");
    } finally {
      setLoading(false);
    }
  };

  const getSectionTitle = (index: number, packages: Package[]) => {
    if (index === 0) return "KEY FEATURES:";
    return `EVERYTHING IN ${packages[index - 1].name.toUpperCase()} +`;
  };

  const getButtonStyle = (pkg: Package) => {
    if (pkg.isPopular) {
      return "bg-white text-gray-900 hover:bg-gray-100";
    }
    
    const packageIndex = packages.findIndex(p => p.id === pkg.id);
    if (packageIndex === 1) {
      return "bg-gray-100 text-gray-900 hover:bg-gray-200 border border-gray-200";
    }
    
    if (packageIndex === packages.length - 1 || pkg.price === 0 && pkg.name.toLowerCase().includes('enterprise')) {
      return "bg-white text-gray-700 hover:bg-gray-50 border-2 border-gray-300";
    }
    
    return "bg-gray-900 text-white hover:bg-gray-800";
  };

  const getButtonText = (pkg: Package) => {
    if (pkg.name.toLowerCase().includes('enterprise')) {
      return "Get a Demo";
    }
    if (pkg.price === 0 && pkg.name.toLowerCase().includes('free')) {
      return "Get Started";
    }
    return "Get started";
  };

  const formatPrice = (price: number, currency: string) => {
    return `${currency === "INR" ? "₹" : "$"}${price}`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#fafafa] flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading packages...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-[#fafafa] flex items-center justify-center">
        <div className="text-center">
          <div className="bg-red-50 border border-red-200 rounded-lg p-6 max-w-md">
            <h3 className="text-red-800 font-semibold mb-2">Error Loading Packages</h3>
            <p className="text-red-600 mb-4">{error}</p>
            <button
              onClick={fetchPackages}
              className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition-colors"
            >
              Try Again
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (packages.length === 0) {
    return (
      <div className="min-h-screen bg-[#fafafa] flex items-center justify-center">
        <div className="text-center">
          <p className="text-gray-600 text-lg">No packages available at the moment.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fafafa] py-12 px-8">
      {/* Header Section */}
      <div className="text-center mb-12">
        <div className="flex items-center justify-center gap-2 mb-8">
          <Check className="text-green-600" size={18} />
          <span className="text-gray-700 text-sm font-medium">100% Money-back Guarantee</span>
        </div>

        {/* Billing Toggle */}
        <div className="flex items-center justify-center gap-4">
          <span className="text-sm text-blue-600 font-medium">Save up to 30% with yearly</span>
          <div className="inline-flex rounded-lg border border-gray-300 bg-white p-1 shadow-sm">
            <button
              onClick={() => setBillingCycle("monthly")}
              className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${
                billingCycle === "monthly"
                  ? "bg-gray-100 text-gray-900 shadow-sm"
                  : "text-gray-600 hover:text-gray-900"
              }`}
            >
              Monthly
            </button>
            <button
              onClick={() => setBillingCycle("yearly")}
              className={`px-6 py-2 rounded-md text-sm font-medium transition-all ${
                billingCycle === "yearly"
                  ? "bg-gray-100 text-gray-900 shadow-sm"
                  : "text-gray-600 hover:text-gray-900"
              }`}
            >
              Yearly
            </button>
          </div>
        </div>
      </div>

      {/* Pricing Cards Grid */}
      <div className="max-w-[1400px] mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
        {packages.map((pkg, index) => {
          const features = Array.isArray(pkg.features) 
            ? pkg.features 
            : typeof pkg.features === 'object' 
              ? Object.values(pkg.features) 
              : [];

          return (
            <div
              key={pkg.id}
              className={`relative rounded-xl border overflow-hidden flex flex-col ${
                pkg.isPopular
                  ? "bg-[#1a1d29] border-[#1a1d29] shadow-xl"
                  : "bg-white border-gray-200 shadow-sm"
              }`}
            >
              {/* Popular Badge */}
              {pkg.isPopular && (
                <div className="absolute top-5 right-5 z-10">
                  <span className="inline-flex items-center rounded-full bg-white px-3 py-1 text-xs font-semibold text-gray-900">
                    Popular
                  </span>
                </div>
              )}

              {/* Card Content */}
              <div className="p-6 flex flex-col flex-1">
                {/* Header */}
                <div className="mb-6">
                  <h3
                    className={`text-[28px] font-bold mb-3 ${
                      pkg.isPopular ? "text-white" : "text-gray-900"
                    }`}
                  >
                    {pkg.name}
                  </h3>
                  
                  {pkg.description ? (
                    <p className={`text-base mb-2 ${pkg.isPopular ? "text-gray-400" : "text-gray-600"}`}>
                      {pkg.description}
                    </p>
                  ) : null}

                  {pkg.price === 0 && pkg.name.toLowerCase().includes('enterprise') ? (
                    <p className={`text-base ${pkg.isPopular ? "text-gray-400" : "text-gray-600"}`}>
                      Get a custom demo
                    </p>
                  ) : (
                    <>
                      <div className="flex items-baseline gap-0 mb-1">
                        <span
                          className={`text-5xl font-bold ${
                            pkg.isPopular ? "text-white" : "text-gray-900"
                          }`}
                        >
                          {formatPrice(Number(pkg.price), pkg.currency)}
                        </span>
                      </div>
                      <p
                        className={`text-sm mt-1 ${
                          pkg.isPopular ? "text-gray-400" : "text-gray-600"
                        }`}
                      >
                        Per user/month, billed yearly
                      </p>
                    </>
                  )}
                </div>

                {/* CTA Button */}
                <button
                  className={`w-full py-3 px-4 rounded-lg font-medium text-base transition-all mb-8 ${getButtonStyle(pkg)}`}
                >
                  {getButtonText(pkg)}
                </button>

                {/* Features Section */}
                <div className="flex-1">
                  <p
                    className={`text-[11px] font-bold tracking-wider mb-5 uppercase ${
                      pkg.isPopular ? "text-gray-500" : "text-gray-500"
                    }`}
                  >
                    {getSectionTitle(index, packages)}
                  </p>
                  <ul className="space-y-3">
                    {features.map((feature: any, idx: number) => {
                      const featureName = typeof feature === 'string' 
                        ? feature 
                        : feature.name || feature.title || '';
                      
                      return (
                        <li key={idx} className="flex items-start gap-3">
                          <Check
                            className={`flex-shrink-0 mt-0.5 ${
                              pkg.isPopular ? "text-white" : "text-gray-900"
                            }`}
                            size={16}
                            strokeWidth={2.5}
                          />
                          <span
                            className={`text-[15px] leading-snug ${
                              pkg.isPopular ? "text-white" : "text-gray-700"
                            }`}
                          >
                            {featureName}
                          </span>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}